glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 uv;
out vec4 color;
vec4 vert () { uv=a_texCoord; color=a_color; return cc_matViewProj*vec4(a_position,1.0); }
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
in vec2 uv;
in vec4 color;
layout(std140) uniform RibbonParams { vec4 params; };
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);}
float fbm(vec2 p){return noise(p)*.57+noise(p*2.03+3.1)*.28+noise(p*4.07+7.3)*.15;}
vec4 frag () {
  float u=uv.x,v=uv.y,time=params.x,track=params.z;
  vec2 q=vec2(u*10.0-time*1.9+track*17.0,v*1.55);
  float n=fbm(q+vec2(0.0,sin(u*13.0-time*2.5)*.6));
  float curl=sin(u*19.0-time*4.2)*.11+(n-.5)*.62;
  float d=1.0-abs(v+curl);
  float holes=fbm(vec2(u*17.0-time*2.7,v*2.0+time*.16));
  float edge=smoothstep(.015,.31,d-(holes-.5)*.34);
  float fade=smoothstep(0.0,.10,u)*(1.0-smoothstep(.965,1.0,u));
  float hot=clamp(d*.88+(n-.42)*.95,0.0,1.0);
  vec3 red=vec3(1.0,.12,.018),orange=vec3(1.0,.39,.035),gold=vec3(1.0,.87,.32);
  vec3 c=mix(red,orange,smoothstep(.10,.55,hot));
  c=mix(c,gold,smoothstep(.57,.94,hot));
  if(params.w>0.5){ edge=smoothstep(-.25,.65,d); c=mix(red,orange,.25); }
  float a=edge*fade*params.y*(.66+.28*hot)*color.a;
  return vec4(c*a,a);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

